INSERT INTO questionnaires (language, questionnaire) VALUES ('RO', '{"info":[{"QuestionType":"intro","settings":{"RichText":"<h1>Bine ai venit</h1><p>Menopauza nu este sfârșitul unei etape, ci o parte firească din viața ta, în care ai nevoie de informații clare și sprijin potrivit.</p><p>Chestionarul nostru te ajută să îți identifici etapa în care te afli în călătoria menopauzei și îți oferă informații bazate pe știință pentru a-ți susține sănătatea.<br><br>Nu ești singură în această călătorie.<br>Suntem aici să îți oferim claritate și sprijin real.</p><p>Să începem.</p>"},"DataPointName":"WelcomeMessage","position":1},{"QuestionType":"media","settings":{"RichText":"<h1>Peste 1000 de femei<br>au ales evrbloom</h1>","MediaUrl":"https://cdn.shopify.com/s/files/1/0799/1132/1784/files/community.png"},"DataPointName":"Media","position":2},{"QuestionType":"first_name","settings":{"QuestionHelper":"Te rugăm să introduci prenumele tău.","QuestionText":"Care este prenumele tău?"},"DataPointName":"FirstName","position":3},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Acest câmp este obligatoriu.","label":"Anul nașterii","type":"numeric","mandatory":true,"measurement":"An"}],"QuestionHelper":"Te rugăm să introduci anul în care te-ai născut.","QuestionText":"Care este anul tău de naștere?"},"DataPointName":"BirthYear","position":4},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Acest câmp este obligatoriu.","label":"Înălțime","type":"numeric","mandatory":true,"measurement":"cm"}],"QuestionHelper":"Te rugăm să introduci înălțimea ta în centimetri.","QuestionText":"Care este înălțimea ta?"},"DataPointName":"Height","position":5},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"Acest câmp este obligatoriu.","label":"Greutate","type":"numeric","mandatory":true,"measurement":"kg"}],"QuestionHelper":"Te rugăm să introduci greutatea ta în kilograme.","QuestionText":"Care este greutatea ta actuală?"},"DataPointName":"Weight","position":6},{"QuestionType":"single_option","settings":{"options":[{"OptionText":"Am menstruații regulate."},{"OptionText":"Am menstruații regulate, dar s-au schimbat ca durată sau cantitate."},{"OptionText":"Am menstruații neregulate și uneori trec luni fără să am menstruație."},{"OptionText":"Nu am avut menstruație de câteva luni, dar de mai puțin de un an."},{"OptionText":"Nu am avut menstruație de un an sau mai mult."}],"QuestionHelper":"Alege varianta care ți se potrivește cel mai bine.","QuestionText":"Cum este menstruația ta în prezent?"},"DataPointName":"Menstrual Status","position":7},{"QuestionType":"single_option","settings":{"options":[{"OptionText":"Nu am utilizat niciodată terapia hormonală de substituție."},{"OptionText":"Utilizez în prezent terapia hormonală de substituție."},{"OptionText":"Am utilizat terapia hormonală de substituție în trecut."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine experiența ta.","QuestionText":"Ai utilizat sau utilizezi în prezent terapia hormonală de substituție?"},"DataPointName":"HRT Treatment History","position":8},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am bufeuri."},{"OptionValue":2,"OptionText":"Ocazional, de câteva ori pe lună."},{"OptionValue":3,"OptionText":"Frecvent, de mai multe ori pe săptămână."},{"OptionValue":4,"OptionText":"Severe, zilnic sau constant pe parcursul zilei și nopții."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai bufeuri.","QuestionText":"Cât de des ai bufeuri?"},"DataPointName":"Hot Flushes","position":9},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am transpirații nocturne."},{"OptionValue":2,"OptionText":"Ocazional, de câteva ori pe lună."},{"OptionValue":3,"OptionText":"Frecvent, de mai multe ori pe săptămână."},{"OptionValue":4,"OptionText":"Severe, îmi perturbă somnul aproape în fiecare noapte."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai transpirații nocturne.","QuestionText":"Cât de des ai transpirații nocturne?"},"DataPointName":"Night Sweats","position":10},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am palpitații."},{"OptionValue":2,"OptionText":"Ocazional, de câteva ori pe lună."},{"OptionValue":3,"OptionText":"Frecvent, de mai multe ori pe săptămână."},{"OptionValue":4,"OptionText":"Severe, aproape zilnic și deranjante."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai palpitații.","QuestionText":"Cât de des ai palpitații?"},"DataPointName":"Palpitations","position":11},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am dureri articulare sau musculare."},{"OptionValue":2,"OptionText":"Ușoare, rigiditate sau disconfort ocazional."},{"OptionValue":3,"OptionText":"Durere frecventă, afectează mișcarea și activitățile zilnice."},{"OptionValue":4,"OptionText":"Durere severă, persistentă, care limitează activitățile."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai disconfort articular sau muscular.","QuestionText":"Cât de des ai dureri articulare sau musculare?"},"DataPointName":"Joint Pain","position":12},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am observat nicio creștere în greutate."},{"OptionValue":2,"OptionText":"Am luat puțin în greutate, dar nu mă deranjează."},{"OptionValue":3,"OptionText":"Am observat o creștere vizibilă în greutate, care îmi afectează încrederea."},{"OptionValue":4,"OptionText":"Am luat semnificativ în greutate și îmi este greu să controlez acest lucru, chiar dacă fac eforturi."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de mult s-a schimbat greutatea ta recent.","QuestionText":"Cât de mult s-a schimbat greutatea ta recent?"},"DataPointName":"Weight Gain","position":13},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nicio schimbare, libidoul meu este la fel."},{"OptionValue":2,"OptionText":"Am observat o scădere ușoară, dar încă am interes."},{"OptionValue":3,"OptionText":"Am o scădere vizibilă a interesului, care îmi afectează relația."},{"OptionValue":4,"OptionText":"Am pierdut aproape complet interesul pentru sex."}],"QuestionHelper":"Alege varianta care ți se potrivește cel mai bine:","QuestionText":"Cum este interesul tău pentru sex în prezent?"},"DataPointName":"Loss of Interest in Sex","position":14},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am probleme urinare, totul este normal."},{"OptionValue":2,"OptionText":"Urgență ocazională sau mici pierderi de urină."},{"OptionValue":3,"OptionText":"Scurgeri frecvente sau urgență, afectează viața zilnică."},{"OptionValue":4,"OptionText":"Probleme severe de control al vezicii, impact semnificativ asupra mea."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai probleme urinare.","QuestionText":"Cât de des ai probleme urinare precum urgență, scurgeri sau infecții?"},"DataPointName":"Bladder Problems","position":15},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am uscăciune sau disconfort vaginal."},{"OptionValue":2,"OptionText":"Uscăciune ușoară ocazională, fără disconfort."},{"OptionValue":3,"OptionText":"Uscăciune vizibilă, dar gestionabilă."},{"OptionValue":4,"OptionText":"Uscăciune frecventă, provocând disconfort."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de mult te-a afectat uscăciunea vaginală.","QuestionText":"Cât de mult te-a afectat uscăciunea vaginală recent?"},"DataPointName":"Vaginal Dryness","position":16},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nicio schimbare, pielea mea este la fel."},{"OptionValue":2,"OptionText":"Ușoară uscăciune sau schimbare de textură."},{"OptionValue":3,"OptionText":"Schimbare moderată, linii fine sau ten tern vizibil."},{"OptionValue":4,"OptionText":"Uscăciune frecventă, pierdere de fermitate."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cum s-a schimbat pielea ta recent.","QuestionText":"Cum s-a schimbat pielea ta recent?"},"DataPointName":"Declining Skin Quality","position":17},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nicio schimbare, părul meu este la fel."},{"OptionValue":2,"OptionText":"Ușoară subțiere sau schimbare de textură."},{"OptionValue":3,"OptionText":"Cădere moderată sau uscăciune crescută."},{"OptionValue":4,"OptionText":"Cădere frecventă, subțiere vizibilă."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cum s-a schimbat părul tău recent.","QuestionText":"Cum s-a schimbat părul tău recent?"},"DataPointName":"Declining Hair Quality","position":18},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Rareori mă simt iritabilă."},{"OptionValue":2,"OptionText":"Ocazional, dar gestionabil."},{"OptionValue":3,"OptionText":"Moderat, îmi afectează starea de spirit."},{"OptionValue":4,"OptionText":"Frecvent, afectează relațiile mele."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des te simți iritabilă.","QuestionText":"Cât de des te simți iritabilă?"},"DataPointName":"Irritability","position":19},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am schimbări de dispoziție sau depresie."},{"OptionValue":2,"OptionText":"Ocazional, dar nu îmi afectează viața zilnică."},{"OptionValue":3,"OptionText":"Schimbări moderate de dispoziție, dar gestionabile."},{"OptionValue":4,"OptionText":"Schimbări frecvente de dispoziție, uneori greu de gestionat."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des experimentezi schimbări de dispoziție sau depresie.","QuestionText":"Cât de des experimentezi schimbări de dispoziție sau depresie?"},"DataPointName":"Low Mood, Depression, Mood Swings","position":20},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Rareori mă simt anxioasă."},{"OptionValue":2,"OptionText":"Ocazional, dar nu îmi afectează viața zilnică."},{"OptionValue":3,"OptionText":"Anxietate moderată, dar gestionabilă."},{"OptionValue":4,"OptionText":"Anxietate frecventă, îmi afectează concentrarea și relaxarea."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des te simți anxioasă sau îngrijorată.","QuestionText":"Cât de des te simți anxioasă sau îngrijorată?"},"DataPointName":"Anxiety","position":21},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Dorm bine, fără probleme."},{"OptionValue":2,"OptionText":"Ocazional, dar nu este o preocupare majoră."},{"OptionValue":3,"OptionText":"Probleme moderate de somn, îmi afectează nivelul de energie."},{"OptionValue":4,"OptionText":"Frecvente, mă trezesc adesea obosită."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai probleme cu somnul.","QuestionText":"Cât de des ai probleme cu somnul?"},"DataPointName":"Sleep Problems","position":22},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Rareori sau niciodată nu am dureri de cap."},{"OptionValue":2,"OptionText":"Ocazional, dar ușoare."},{"OptionValue":3,"OptionText":"Moderate, dar gestionabile."},{"OptionValue":4,"OptionText":"Frecvente, îmi afectează viața zilnică."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai dureri de cap.","QuestionText":"Cât de des ai dureri de cap?"},"DataPointName":"Headaches","position":23},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu experimentez probleme cu claritatea mentală."},{"OptionValue":2,"OptionText":"Ocazional, dar nu mă îngrijorează."},{"OptionValue":3,"OptionText":"Moderate, uneori mă simt încetinită mental."},{"OptionValue":4,"OptionText":"Frecvente, îmi afectează concentrarea și memoria."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des experimentezi probleme de claritate mentală.","QuestionText":"Cât de des experimentezi senzația de „ceață mentală”?"},"DataPointName":"Brain Fog","position":24},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am probleme cu memoria."},{"OptionValue":2,"OptionText":"Ocazional, dar nu mă îngrijorează."},{"OptionValue":3,"OptionText":"Moderate, dar gestionabile."},{"OptionValue":4,"OptionText":"Frecvente, îmi afectează viața zilnică."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des ai probleme de memorie.","QuestionText":"Cât de des ai probleme de memorie?"},"DataPointName":"Memory Issues","position":25},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu experimentez oboseală."},{"OptionValue":2,"OptionText":"Ocazional, dar ușoară."},{"OptionValue":3,"OptionText":"Moderată, dar gestionabilă."},{"OptionValue":4,"OptionText":"Frecventă, îmi afectează viața zilnică."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des te simți obosită.","QuestionText":"Cât de des te simți obosită?"},"DataPointName":"Tiredness & Fatigue","position":26},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nicio schimbare, mă simt la fel de puternică."},{"OptionValue":2,"OptionText":"Ușor mai slăbită, dar fără probleme majore."},{"OptionValue":3,"OptionText":"Moderată, dar gestionabilă."},{"OptionValue":4,"OptionText":"Frecventă slăbiciune, îmi afectează activitățile zilnice."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de mult ți-a scăzut forța sau rezistența fizică.","QuestionText":"Cât de mult ți-a scăzut forța sau rezistența fizică?"},"DataPointName":"Decreased Physical Strength or Stamina","position":27},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"Nu am probleme digestive."},{"OptionValue":2,"OptionText":"Ocazional, dar ușoare."},{"OptionValue":3,"OptionText":"Moderate, dar gestionabile."},{"OptionValue":4,"OptionText":"Frecvente, îmi afectează confortul zilnic."}],"QuestionHelper":"Alege opțiunea care descrie cel mai bine cât de des experimentezi probleme digestive precum balonare, gaze sau disconfort.","QuestionText":"Cât de des experimentezi probleme digestive precum balonare, gaze sau disconfort?"},"DataPointName":"DigestiveSymptoms","position":28},{"QuestionType":"email","settings":{"QuestionHelper":"Te rugăm să introduci o adresă de e-mail validă pentru a putea primi rezultatele tale.","QuestionText":"Care este adresa ta de e-mail?"},"DataPointName":"Email","position":29}]}'::jsonb);
INSERT INTO questionnaires (language, questionnaire) VALUES ('EN', '{"info":[{"QuestionType":"intro","settings":{"RichText":"<h1>Welcome to menoQueens<h1><p>Our questionnaire determines your stage in the menopause journey and provides science-backed insights to support your health. </p><p>The Menopause Score calculator helps you understand how menopause is impacting your life and how you can improve your well-being with the right insights and support.</p><p>Answer honestly to get the most accurate results.</p><p>Let''s begin!</p>"},"DataPointName":"WelcomeMessage","position":1},{"QuestionType":"first_name","settings":{"QuestionHelper":"Please enter your first name.","QuestionText":"What is your first name?"},"DataPointName":"FirstName","position":2},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"This field is required.","label":"Year of Birth","type":"numeric","mandatory":true,"measurement":"Year"}],"QuestionHelper":"Please enter the year you were born.","QuestionText":"What is your year of birth?"},"DataPointName":"BirthYear","position":3},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"This field is required.","label":"Height","type":"numeric","mandatory":true,"measurement":"cm"}],"QuestionHelper":"Please enter your height in centimeters.","QuestionText":"What’s your current height?"},"DataPointName":"Height","position":4},{"QuestionType":"custom_form","settings":{"fields":[{"error_message":"This field is required.","label":"Weight","type":"numeric","mandatory":true,"measurement":"kg"}],"QuestionHelper":"Please enter your weight in kilograms.","QuestionText":"What’s your current weight?"},"DataPointName":"Weight","position":5},{"QuestionType":"single_option","settings":{"options":[{"OptionText":"I have regular periods."},{"OptionText":"My periods are still regular but have changed in length or flow."},{"OptionText":"I experience irregular periods and sometimes skip months."},{"OptionText":"I haven’t had a period for several months but less than a year."},{"OptionText":"I haven’t had a period for a year or more."}],"QuestionHelper":"Select the option that best describes your current menstrual cycle pattern or status, based on your recent experiences.","QuestionText":"Select the option that best describes your current menstrual status."},"DataPointName":"Menstrual Status","position":6},{"QuestionType":"single_option","settings":{"options":[{"OptionText":"I am currently taking HRT"},{"OptionText":"I have taken HRT in the past"},{"OptionText":"I have never taken HRT"}],"QuestionHelper":"Select the option that best describes your experience with hormone replacement therapy (HRT), including any past or current use.","QuestionText":"Have you ever, or are you currently, taking any forms of menopausal hormonal treatment (HRT)?"},"DataPointName":"HRT Treatment History","position":7},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience hot flushes"},{"OptionValue":2,"OptionText":"Occasionally, a few times per month"},{"OptionValue":3,"OptionText":"Frequently, multiple times per week"},{"OptionValue":4,"OptionText":"Severe, daily or constant throughout the day and night"}],"QuestionHelper":"Select the option that best describes how often you experience hot flushes.","QuestionText":"How often do you experience hot flushes?"},"DataPointName":"Hot Flushes","position":8},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience night sweats"},{"OptionValue":2,"OptionText":"Occasionally, a few times per month"},{"OptionValue":3,"OptionText":"Frequently, multiple times per week"},{"OptionValue":4,"OptionText":"Severe, disrupting my sleep almost every night"}],"QuestionHelper":"Select the option that best describes how often you experience night sweats.","QuestionText":"How often do you experience night sweats?"},"DataPointName":"Night Sweats","position":9},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience palpitations"},{"OptionValue":2,"OptionText":"Occasionally, a few times per month"},{"OptionValue":3,"OptionText":"Frequently, multiple times per week"},{"OptionValue":4,"OptionText":"Severe, almost daily and distressing"}],"QuestionHelper":"Select the option that best describes how often you experience palpitations.","QuestionText":"How often do you experience palpitations?"},"DataPointName":"Palpitations","position":10},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience joint or muscle discomfort"},{"OptionValue":2,"OptionText":"Mild, occasional stiffness or discomfort"},{"OptionValue":3,"OptionText":"Frequent pain, affecting movement and daily tasks"},{"OptionValue":4,"OptionText":"Severe, persistent pain that limits activity"}],"QuestionHelper":"Select the option that best describes how often you experience joint or muscle discomfort.","QuestionText":"How often do you experience joint or muscle discomfort?"},"DataPointName":"Joint Pain","position":11},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I haven’t noticed any weight gain"},{"OptionValue":2,"OptionText":"Mild weight gain, but not bothersome"},{"OptionValue":3,"OptionText":"Noticeable weight gain, impacting my confidence"},{"OptionValue":4,"OptionText":"Significant weight gain, hard to control despite efforts"}],"QuestionHelper":"Select the option that best describes how much your weight has changed recently.","QuestionText":"How much has your weight changed recently?"},"DataPointName":"Weight Gain","position":12},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No change, my sex drive is the same"},{"OptionValue":2,"OptionText":"Slight decrease, but I still have interest"},{"OptionValue":3,"OptionText":"Noticeable decrease, affecting my relationship"},{"OptionValue":4,"OptionText":"Severe loss, I have little to no interest in sex"}],"QuestionHelper":"Select the option that best describes how much your interest in sex has changed.","QuestionText":"How much has your interest in sex changed?"},"DataPointName":"Loss of Interest in Sex","position":13},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No bladder issues, everything feels normal"},{"OptionValue":2,"OptionText":"Occasional urgency or minor leaks"},{"OptionValue":3,"OptionText":"Frequent leaks or urgency, affecting daily life"},{"OptionValue":4,"OptionText":"Severe bladder control issues, significantly impacting me"}],"QuestionHelper":"Select the option that best describes how often you experience bladder problems (e.g., infections, leaks, urgency).","QuestionText":"How often do you experience bladder problems like urgency, leaks, or infections?"},"DataPointName":"Bladder Problems","position":14},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No dryness or discomfort"},{"OptionValue":2,"OptionText":"Occasional mild dryness, no discomfort"},{"OptionValue":3,"OptionText":"Noticeable dryness, but manageable"},{"OptionValue":4,"OptionText":"Frequent dryness, causing discomfort"}],"QuestionHelper":"Select the option that best describes how much vaginal dryness has affected you.","QuestionText":"How much has vaginal dryness affected you recently?"},"DataPointName":"Vaginal Dryness","position":15},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No change, my skin is the same"},{"OptionValue":2,"OptionText":"Mild dryness or slight texture change"},{"OptionValue":3,"OptionText":"Moderate change, noticeable fine lines or dullness"},{"OptionValue":4,"OptionText":"Frequent dryness, loss of firmness"}],"QuestionHelper":"Select the option that best describes how your skin has changed recently.","QuestionText":"How has your skin changed recently?"},"DataPointName":"Declining Skin Quality","position":16},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No change, my hair is the same"},{"OptionValue":2,"OptionText":"Mild thinning or slight texture change"},{"OptionValue":3,"OptionText":"Moderate shedding or increased dryness"},{"OptionValue":4,"OptionText":"Frequent shedding, noticeable thinning"}],"QuestionHelper":"Select the option that best describes how your hair has changed recently.","QuestionText":"How has your hair changed recently?"},"DataPointName":"Declining Hair Quality","position":17},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I rarely feel irritable"},{"OptionValue":2,"OptionText":"Occasionally, but manageable"},{"OptionValue":3,"OptionText":"Moderate, affecting my mood"},{"OptionValue":4,"OptionText":"Frequent, impacting my relationships"}],"QuestionHelper":"Select the option that best describes how often you feel irritable.","QuestionText":"How often do you feel irritable?"},"DataPointName":"Irritability","position":18},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience mood changes or depression"},{"OptionValue":2,"OptionText":"Occasionally, but it doesn’t impact my daily life"},{"OptionValue":3,"OptionText":"Moderate mood swings, but manageable"},{"OptionValue":4,"OptionText":"Frequent mood changes, sometimes hard to handle"}],"QuestionHelper":"Select the option that best describes how often you experience low mood, depression, or mood swings.","QuestionText":"How often do you experience low mood, depression, or mood swings?"},"DataPointName":"Low Mood, Depression, Mood Swings","position":19},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I rarely feel anxious"},{"OptionValue":2,"OptionText":"Occasionally, but it doesn’t affect my daily life"},{"OptionValue":3,"OptionText":"Moderate anxiety, but manageable"},{"OptionValue":4,"OptionText":"Frequent anxiety, affecting my focus and relaxation"}],"QuestionHelper":"Select the option that best describes how often you feel anxious or worried.","QuestionText":"How often do you feel anxious or worried?"},"DataPointName":"Anxiety","position":20},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I sleep well without any issues"},{"OptionValue":2,"OptionText":"Occasionally, but not a major concern"},{"OptionValue":3,"OptionText":"Moderate, affecting my energy levels"},{"OptionValue":4,"OptionText":"Frequent, I often wake up feeling tired"}],"QuestionHelper":"Select the option that best describes how often you experience sleep problems.","QuestionText":"How often do you experience sleep problems?"},"DataPointName":"Sleep Problems","position":21},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I rarely or never have headaches"},{"OptionValue":2,"OptionText":"Occasionally, but mild"},{"OptionValue":3,"OptionText":"Moderate, but manageable"},{"OptionValue":4,"OptionText":"Frequent, affecting my daily life"}],"QuestionHelper":"Select the option that best describes how often you experience headaches.","QuestionText":"How often do you experience headaches?"},"DataPointName":"Headaches","position":22},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience brain fog"},{"OptionValue":2,"OptionText":"Occasionally, but not concerning"},{"OptionValue":3,"OptionText":"Moderate, I sometimes feel mentally slow"},{"OptionValue":4,"OptionText":"Frequent, affecting my focus and memory"}],"QuestionHelper":"Select the option that best describes how often you experience brain fog.","QuestionText":"How often do you experience brain fog?"},"DataPointName":"Brain Fog","position":23},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t have memory problems"},{"OptionValue":2,"OptionText":"Occasionally, but not concerning"},{"OptionValue":3,"OptionText":"Moderate, but manageable"},{"OptionValue":4,"OptionText":"Frequent, affecting my daily life"}],"QuestionHelper":"Select the option that best describes how often you experience memory problems.","QuestionText":"How often do you experience memory problems?"},"DataPointName":"Memory Issues","position":24},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience fatigue"},{"OptionValue":2,"OptionText":"Occasionally, but mild"},{"OptionValue":3,"OptionText":"Moderate, but manageable"},{"OptionValue":4,"OptionText":"Frequent, affecting my daily life"}],"QuestionHelper":"Select the option that best describes how often you feel tired or fatigued.","QuestionText":"How often do you feel tired or fatigued?"},"DataPointName":"Tiredness & Fatigue","position":25},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"No change, I feel as strong as before"},{"OptionValue":2,"OptionText":"Slightly weaker, but no major issues"},{"OptionValue":3,"OptionText":"Moderate, but manageable"},{"OptionValue":4,"OptionText":"Frequent weakness, affecting daily tasks"}],"QuestionHelper":"Select the option that best describes how much your physical strength or stamina has decreased.","QuestionText":"How much has your physical strength or stamina decreased?"},"DataPointName":"Decreased Physical Strength or Stamina","position":26},{"QuestionType":"scale","settings":{"options":[{"OptionValue":1,"OptionText":"I don’t experience digestive issues"},{"OptionValue":2,"OptionText":"Occasionally, but mild"},{"OptionValue":3,"OptionText":"Moderate, but manageable"},{"OptionValue":4,"OptionText":"Frequent, affecting my daily comfort"}],"QuestionHelper":"Select the option that best describes how often you experience digestive symptoms like bloating, gas, or discomfort.","QuestionText":"How often do you experience digestive symptoms like bloating, gas, or discomfort?"},"DataPointName":"DigestiveSymptoms","position":27},{"QuestionType":"email","settings":{"QuestionHelper":"Please enter a valid email address so we can follow up with your results.","QuestionText":"What is your email address?"},"DataPointName":"Email","position":28}]}'::jsonb);
